const evt=$input.first().json?.raw_data||$input.first().json;
const PLAYBOOKS={
  'brute_force':{name:'Brute Force Response',steps:['Block source IP','Force MFA re-auth on target account','Check for successful auth in window','Review account for compromise'],sla_hours:1,team:'SOC',severity:'High'},
  'malware':{name:'Malware Containment',steps:['Isolate endpoint from network','Capture memory dump','Scan for persistence','Wipe and reimage if confirmed'],sla_hours:2,team:'IR',severity:'Critical'},
  'data_exfil':{name:'Data Exfiltration Response',steps:['Block egress IP/domain','Capture network pcap','Identify data accessed','Notify DPO if PII involved'],sla_hours:1,team:'IR',severity:'Critical'},
  'phishing':{name:'Phishing Incident',steps:['Pull email from all mailboxes','Block sender domain','Check for credential submission','Scan clicked-link hosts'],sla_hours:2,team:'SOC',severity:'Medium'},
  'insider_threat':{name:'Insider Threat Protocol',steps:['Preserve evidence before alerting HR','Capture all logs for past 30 days','Identify data accessed','Legal hold on accounts'],sla_hours:4,team:'CISO',severity:'Critical'},
  'ransomware':{name:'Ransomware Response',steps:['IMMEDIATE: Isolate all affected hosts','Notify CISO and legal NOW','Identify patient zero','Assess backup integrity'],sla_hours:0.5,team:'CISO',severity:'Critical'},
  'cloud_breach':{name:'Cloud Breach Response',steps:['Rotate all IAM keys immediately','Review CloudTrail for 72hrs','Identify affected resources','Assess data exposure'],sla_hours:1,team:'Cloud',severity:'Critical'},
  'default':{name:'Generic Security Incident',steps:['Gather evidence','Assess scope','Contain if possible','Document timeline'],sla_hours:4,team:'SOC',severity:'Medium'}
};
const type=evt.incident_type||evt.event_type||'default';
const pb=PLAYBOOKS[type]||PLAYBOOKS['default'];
const inc_id=`INC-${Date.now()}`;
const due=new Date(Date.now()+pb.sla_hours*3600000).toISOString();
return[{json:{incident_id:inc_id,playbook:pb.name,type,steps:pb.steps,sla_hours:pb.sla_hours,due_at:due,team:pb.team,severity:pb.severity,source:evt.source||'unknown',description:evt.description||evt.raw_data?.rule_desc||'Incident detected'}}];
